const limits={mainland:[29526,40034,50542,61050,71558,82066,92574,103082],alaska:[36908,50043,63178,76313,89448,102583,115718,128853],hawaii:[33966,46047,58127,70208,82288,94369,106449,118530]};
function screenNutrition(a,today=new Date()){
 if(!['yes','no','unsure'].includes(a.family)||!['yes','no','unsure'].includes(a.benefits))throw new Error('Please answer the two required questions.');
 let result={status:'check',title:'The official checker is your next step.',text:'A few more details are needed to check your family’s situation. You can also ask a local agency for help.',limit:null};
 if(a.family==='no')return {...result,status:'other',title:'Start with other food support.',text:'This nutrition program has specific pregnancy, postpartum, breastfeeding, and child-age categories. Based on your answer, food assistance for a wider range of households may be a better starting point. If you are unsure about a category, use the official nutrition-program checker.'};
 if(a.family==='unsure')return result;
 if(a.benefits==='yes')return {...result,status:'pathway',title:'You may have an income-eligibility pathway.',text:'Your family-stage answer fits a basic program category. The benefits you receive may also establish income eligibility. A local agency still needs to confirm all requirements and complete a nutrition assessment.'};
 const current=today>=new Date('2026-07-01T00:00:00Z')&&today<new Date('2027-07-01T00:00:00Z');
 if(!current)return {...result,text:'The income guide on this page needs updating. Use the official checker for current limits; no income comparison was made.'};
 if(!limits[a.region]||a.size===''||a.income==='')return result;
 const size=Number(a.size),income=Number(a.income);
 if(!Number.isInteger(size)||size<1||size>30||!Number.isFinite(income)||income<0)throw new Error('Enter a household size from 1 to 30 and a nonnegative annual income, or leave the optional fields blank.');
 const limit=size<=8?limits[a.region][size-1]:limits[a.region][7]+(size-8)*({mainland:10508,alaska:13135,hawaii:12081}[a.region]);
 if(income<=limit)return {...result,status:'within',limit,title:'Your answers are within the basic guide.',text:'Your family-stage answer fits a program category, and the income you entered is at or below the federal maximum income guide. This is a reason to check—not an approval. Your agency confirms local rules, income counting, residency, and nutrition requirements.'};
 return {...result,status:'above',limit,title:'Above the income guide? Still check the details.',text:'The amount entered is above this federal guide. That is not a denial. Income exclusions, household counting, or eligibility through another benefit may matter. Use the official checker before ruling support out.'};
}
(() => {
'use strict';
const form=document.querySelector('#resource-form'),steps=[...form.querySelectorAll('[data-finder-step]')],results=document.querySelector('#finder-results');let step=0;
form.hidden=false;
function showStep(n,focus=false){step=n;steps.forEach((s,i)=>{s.hidden=i!==n;});document.querySelector('#finder-progress').textContent=`${n+1} of 4 / ${['What would help?','Your household','Your location','Optional income'][n]}`;document.querySelector('#finder-back').hidden=n===0;document.querySelector('#finder-next').hidden=n===3;document.querySelector('#finder-submit').hidden=n!==3;if(focus){const legend=steps[n].querySelector('legend');legend.tabIndex=-1;legend.focus();}}
function valid(){return [...steps[step].querySelectorAll('input')].every(i=>i.reportValidity());}
document.querySelector('#finder-next').onclick=()=>{if(valid())showStep(step+1,true);};document.querySelector('#finder-back').onclick=()=>showStep(step-1,true);
function card(title,why,body,url){const a=document.createElement('article'),h=document.createElement('h3'),reason=document.createElement('p'),p=document.createElement('p'),link=document.createElement('a');h.textContent=title;reason.className='match-reason';reason.textContent=why;p.textContent=body;link.href=url;link.textContent='Check the official requirements →';a.append(h,reason,p,link);document.querySelector('#program-results').append(a);return a;}
form.addEventListener('submit',e=>{e.preventDefault();if(!valid())return;if(step<3){showStep(step+1,true);return;}const need=[...form.querySelectorAll('[name=need]:checked')].map(x=>x.value),sit=[...form.querySelectorAll('[name=situation]:checked')].map(x=>x.value),has=x=>sit.includes(x),wants=x=>need.includes(x),age=document.querySelector('#age-band').value,state=document.querySelector('#finder-state').value;const young=['pregnant','postpartum','breastfeeding','young'].some(has),child=young||has('child'),older=['60-64','65plus'].includes(age),all=need.length===0;document.querySelector('#program-results').replaceChildren();
if(young){const a=card('WIC','A pregnancy, postpartum, breastfeeding, or under-five category applies.','Food benefits, nutrition and breastfeeding support, and referrals. A local agency completes the eligibility assessment.','https://www.usa.gov/food-assistance');const size=document.querySelector('#household-size').value,income=document.querySelector('#finder-income').value,benefits=document.querySelector('#existing-benefits').value;const region=state==='AK'?'alaska':state==='HI'?'hawaii':'mainland';const covered=Boolean(state);const r=screenNutrition({family:'yes',benefits,region:covered?region:'',size,income});const note=document.createElement('p');note.className='income-note';note.textContent=r.title+' '+r.text+(r.limit!==null?' Federal annual guide: $'+r.limit.toLocaleString('en-US')+' (July 2026–June 2027).':'');a.append(note);}
if(wants('food')||all)card('SNAP food assistance','You selected groceries, or left the needs question open.','SNAP can help with food costs. State income, household, and other rules apply.','https://www.usa.gov/food-stamps');
if(wants('health')||child||has('disability')||all)card('Medicaid & CHIP',child?'Your household includes pregnancy or children.':'Health coverage may be useful for your situation.','Check your state’s health coverage programs. Children may qualify for CHIP even when household income is too high for Medicaid.','https://www.usa.gov/medicaid-chip-insurance');
if(age==='65plus'||has('disability'))card('Medicare',age==='65plus'?'You selected age 65 or older.':'Some people qualify before 65 through disability or particular conditions.','Check enrollment timing and coverage rules, including help with Medicare costs. A disability alone does not establish eligibility.','https://www.usa.gov/medicare');
if(wants('housing')||all)card('Housing assistance','You selected housing, or left the needs question open.','Explore rental assistance, public housing, and emergency housing. Availability and waiting lists vary locally.','https://www.usa.gov/housing-help');
if(wants('utilities')||all)card('Help with utility bills','You selected utilities, or left the needs question open.','Explore energy assistance, weatherization, and telephone or internet discounts. Each program has its own rules.','https://www.usa.gov/help-with-utility-bills');
if(wants('cash')||all)card('Cash & financial assistance','You selected income support, or left the needs question open.','Explore state assistance, including TANF for qualifying families. Program rules and available support differ.','https://www.usa.gov/welfare-and-financial-assistance');
if(has('disability'))card('Disability benefits & services','You indicated a disability or long-term condition.','Explore SSI, SSDI, employment supports, and caregiver resources. These programs have different medical, work-history, income, and asset requirements.','https://www.usa.gov/disability-services');
if(has('unemployed'))card('Unemployment insurance','You indicated a job loss or reduced hours.','Check the rules in the state where you worked. Your work history and circumstances matter.','https://www.usa.gov/unemployment-benefits');
if(wants('care'))card('Help paying for child care','You selected child care.','Find government information about child care assistance and state programs. Age, income, and activity rules may apply.','https://childcare.gov/consumer-education/get-help-paying-for-child-care');
if(wants('education'))card('Education & training resources','You selected education or training.','Choose Education in the official finder to explore government assistance for your next step.','https://www.usa.gov/benefit-finder');
if(has('working')||wants('tax'))card('Earned Income Tax Credit','You indicated work income or an interest in tax credits.','Use the IRS eligibility guidance. Tax-year rules, earned income, filing status, and qualifying-child requirements matter.','https://www.irs.gov/credits-deductions/individuals/earned-income-tax-credit-eitc');
if(has('veteran'))card('Veterans & military-family benefits','You indicated a military connection.','Explore VA health care, education, disability, and family benefits. Service and program-specific rules apply.','https://www.va.gov/');
if(older)card('Social Security & retirement','You selected age 60 or older.','Explore retirement and survivor benefits and check when you can apply. Selecting this age band is not an eligibility finding.','https://www.usa.gov/social-security');
card('Your state’s benefit agency',state?`You selected ${document.querySelector('#finder-state').selectedOptions[0].textContent}.`:'Your state or territory can help identify additional programs.','Select your location in the official directory to confirm application routes. The directory also lists territorial contacts.','https://www.usa.gov/state-social-services');
document.querySelector('#results-context').textContent='Based on the situations and needs you selected. Income does not filter this list; where applicable, a separate WIC note compares the basic income guide.';results.hidden=false;form.hidden=true;results.focus();});
document.querySelector('#finder-edit').onclick=()=>{results.hidden=true;form.hidden=false;showStep(0,true);};document.querySelector('#finder-clear').onclick=()=>{form.reset();results.hidden=true;document.querySelector('#program-results').replaceChildren();form.hidden=false;showStep(0,true);};showStep(0);
function source(){const id=location.hash.slice(1);if(!id.startsWith('source-'))return;const el=document.getElementById(id);if(el){const d=el.closest('details');if(d)d.open=true;el.scrollIntoView();}}addEventListener('hashchange',source);source();
})();
